151	   * For all the MCP servers associated with this extension:
152	   *
153	   *    - Removes all its MCP servers from the global configuration object.
154	   *    - Disconnects all MCP clients from their servers.
155	   *    - Updates the Gemini chat configuration to load the new tools.
156	   */
157	  async stopExtension(extension: GeminiCLIExtension) {
158	    debugLogger.log(`Unloading extension: ${extension.name}`);
159	    await Promise.all(
160	      Object.keys(extension.mcpServers ?? {}).map((name) => {
